// Some portions generated by Claude

// Unit tests for the shared components in template.ts (formatting, dialogs, popovers and tabs).
const test = require('node:test');
const assert = require('node:assert/strict');

const { createFormBrowserHarness } = require('./form-browser-harness.js');

function loadTemplate() {
    const harness = createFormBrowserHarness();
    harness.loadScripts([]);
    return harness;
}

test('format.count groups integers for the given locale and leaves other text unchanged', () => {
    const format = loadTemplate().context.workbench.format;
    assert.equal(format.count('43685', 'en-US'), '43,685');
    assert.equal(format.count(1234567, 'en-US'), '1,234,567');
    assert.equal(format.count('43685', 'de-DE'), '43.685');
    assert.equal(format.count('Timed out while requesting repository size.', 'en-US'),
        'Timed out while requesting repository size.');
    assert.equal(format.count('', 'en-US'), '');
    assert.equal(format.count(null, 'en-US'), '');
    assert.equal(format.count('12.5', 'en-US'), '12.5');
    assert.equal(format.count('99999999999999999999', 'en-US'), '99999999999999999999');
});
